import { supabase } from "../config/supabaseClient";
import { describeDbError } from "../utils/supabaseErrors";
import { formatTime12h } from "../utils/timeFormat";
import { PRIVACY_NOTICE_VERSION } from "../constants/privacyNotice";
import { isValidPhMobile, INVALID_PH_MOBILE_MESSAGE } from "../utils/validators";

export const APPOINTMENT_STATUSES = ["Confirmed", "Completed", "Cancelled"];

const ACTIVE_STATUSES = ["Confirmed"];
const CLINIC_OPEN_TIME = "09:00";
const CLINIC_CLOSE_TIME = "19:00";
const pad = value => String(value).padStart(2, "0");
const normalizeTime = value => String(value || "").slice(0, 5);
export const addTenMinutes = value => {
  const [hour, minute] = normalizeTime(value).split(":").map(Number);
  const date = new Date(2000, 0, 1, hour, minute + 10);
  return `${pad(date.getHours())}:${pad(date.getMinutes())}`;
};

export function todayLocal() {
  const now = new Date();
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}

function nowMinutesLocal() {
  const now = new Date();
  return now.getHours() * 60 + now.getMinutes();
}

export function formatTime(time) {
  return formatTime12h(normalizeTime(time));
}

export async function getOwners() {
  const { data, error } = await supabase.from("profiles")
    .select("id, full_name, username, email, phone, address, avatar_url")
    .eq("role", "pet_owner").eq("account_status", "active").order("full_name");
  if (error) throw new Error("Unable to load pet owners.");
  return data || [];
}

export async function getPetsByOwner(ownerId) {
  if (!ownerId) return [];
  const { data, error } = await supabase.from("pets")
    .select("id, pet_name, species, breed, owner_id")
    .eq("owner_id", ownerId).eq("is_archived", false).order("pet_name");
  if (error) throw new Error("Unable to load pets. Run appointment_module.sql first.");
  return data || [];
}

export async function getVeterinarians() {
  const { data, error } = await supabase.from("profiles")
    .select("id, full_name, email, role, account_status")
    .order("full_name");
  if (error) {
    console.error("Veterinarian query error:", error);
    throw new Error(`Unable to load veterinarians: ${error.message}`);
  }
  return (data || []).filter((profile) =>
    String(profile.role || "").toLowerCase() === "veterinarian" &&
    String(profile.account_status || "").toLowerCase() === "active"
  );
}

export async function getAvailableSlots(veterinarianId, appointmentDate, excludeAppointmentId = null) {
  if (!veterinarianId || !appointmentDate || appointmentDate < todayLocal()) return [];
  const dayOfWeek = new Date(`${appointmentDate}T12:00:00`).getDay();
  const { data: override, error: overrideError } = await supabase.from("veterinarian_schedule_overrides")
    .select("start_time, end_time, is_available")
    .eq("veterinarian_id", veterinarianId).eq("schedule_date", appointmentDate).maybeSingle();

  const overrideTableMissing = ["42P01", "PGRST205"].includes(overrideError?.code) ||
    String(overrideError?.message || "").toLowerCase().includes("veterinarian_schedule_overrides");

  if (overrideError && !overrideTableMissing) {
    throw new Error("Unable to load the date-specific schedule.");
  }

  // Leave / adjusted hours first, then the schedule staff created for that
  // date (VET_SCHEDULE_CALENDAR.sql). No created schedule means nothing can
  // be booked yet. Before that SQL is run, the weekly roster still applies.
  let schedule = overrideTableMissing ? null : override;
  if (!override) schedule = await getCreatedScheduleDay(veterinarianId, appointmentDate, dayOfWeek);
  if (!schedule || !schedule.is_available || !schedule.start_time || !schedule.end_time) return [];

  let bookedQuery = supabase.from("appointments").select("id, start_time")
    .eq("veterinarian_id", veterinarianId).eq("appointment_date", appointmentDate)
    .in("status", ACTIVE_STATUSES);
  if (excludeAppointmentId) bookedQuery = bookedQuery.neq("id", excludeAppointmentId);
  const { data: booked, error: bookedError } = await bookedQuery;
  if (bookedError) throw new Error("Unable to load booked times.");

  const bookedTimes = new Set((booked || []).map(item => normalizeTime(item.start_time)));
  // Slots offered to another owner in a pending doctor change are held for
  // them until they answer (see QUEUE_DOCTOR_CHANGE_CONFIRMATION.sql).
  const { data: holds } = await supabase.from("queue_doctor_offers").select("proposed_time, pet_ids")
    .eq("proposed_veterinarian_id", veterinarianId).eq("offer_date", appointmentDate).eq("status", "Pending");
  (holds || []).forEach(hold => {
    let time = normalizeTime(hold.proposed_time);
    for (let i = 0; i < Math.max(hold.pet_ids?.length || 0, 1); i++) {
      bookedTimes.add(time);
      time = addTenMinutes(time);
    }
  });
  const slots = [];
  let current = normalizeTime(schedule.start_time);
  if (current < CLINIC_OPEN_TIME) current = CLINIC_OPEN_TIME;

  // PawCruz clinic accepts appointments until closing time, but a vet's
  // own schedule (weekly or a date override) can end earlier than that.
  const scheduleEnd = normalizeTime(schedule.end_time);
  const end = scheduleEnd < CLINIC_CLOSE_TIME ? scheduleEnd : CLINIC_CLOSE_TIME;
  const isToday = appointmentDate === todayLocal();
  const nowMinutes = isToday ? nowMinutesLocal() : -1;
  while (current < end) {
    const [slotHour, slotMinute] = current.split(":").map(Number);
    const isPast = isToday && (slotHour * 60 + slotMinute) <= nowMinutes;
    if (!bookedTimes.has(current) && !isPast) slots.push(current);
    current = addTenMinutes(current);
  }
  return slots;
}

const isMissingRelation = (error, name) =>
  ["42P01", "PGRST205"].includes(error?.code) || String(error?.message || "").toLowerCase().includes(name);

// The created schedule for one vet and date, or null when none was created.
async function getCreatedScheduleDay(veterinarianId, appointmentDate, dayOfWeek) {
  const { data, error } = await supabase.from("veterinarian_schedule_days")
    .select("start_time, end_time, is_available")
    .eq("veterinarian_id", veterinarianId).eq("schedule_date", appointmentDate).maybeSingle();
  if (!error) return data;
  if (!isMissingRelation(error, "veterinarian_schedule_days")) throw new Error("Unable to load the veterinarian schedule.");
  const { data: weekly, error: weeklyError } = await supabase.from("veterinarian_schedules")
    .select("start_time, end_time, is_available")
    .eq("veterinarian_id", veterinarianId).eq("day_of_week", dayOfWeek).maybeSingle();
  if (weeklyError) throw new Error("Unable to load the veterinarian schedule.");
  return weekly;
}

// True when no vet has a created schedule (or adjusted hours) on the date,
// i.e. the clinic hasn't opened that date for booking yet.
export async function isDateUnscheduled(appointmentDate) {
  if (!appointmentDate) return false;
  const [{ data: days, error }, { data: adjusted }] = await Promise.all([
    supabase.from("veterinarian_schedule_days").select("id").eq("schedule_date", appointmentDate).limit(1),
    supabase.from("veterinarian_schedule_overrides").select("id").eq("schedule_date", appointmentDate).is("leave_request_id", null).limit(1)
  ]);
  if (error) return false;
  return !(days || []).length && !(adjusted || []).length;
}

export async function getVeterinarianAvailability(appointmentDate, excludeAppointmentId = null) {
  const vets = await getVeterinarians();
  const perVet = await Promise.all(vets.map(vet => getAvailableSlots(vet.id, appointmentDate, excludeAppointmentId)));
  const slotMap = {};
  const timeSet = new Set();
  vets.forEach((vet, index) => {
    slotMap[vet.id] = perVet[index];
    perVet[index].forEach(time => timeSet.add(time));
  });
  const unscheduled = timeSet.size === 0 ? await isDateUnscheduled(appointmentDate).catch(() => false) : false;
  return { vets, slotMap, times: Array.from(timeSet).sort(), unscheduled };
}

function validatePayload(payload) {
  if (!payload.petId) throw new Error("Select a pet.");
  if (!payload.ownerId) throw new Error("Pet owner is missing.");
  if (!payload.veterinarianId) throw new Error("Select a veterinarian.");
  if (!payload.appointmentDate || payload.appointmentDate < todayLocal()) throw new Error("Select today or a future date.");
  if (!payload.startTime) throw new Error("Select an available time.");
}

export async function createAppointment(payload) {
  validatePayload(payload);

  const latestSlots = await getAvailableSlots(
    payload.veterinarianId,
    payload.appointmentDate
  );
  if (!latestSlots.includes(normalizeTime(payload.startTime))) {
    throw new Error("That appointment time is no longer available. Please choose another time.");
  }

  const row = {
    pet_id: payload.petId,
    owner_id: payload.ownerId,
    veterinarian_id: payload.veterinarianId,
    appointment_date: payload.appointmentDate,
    start_time: payload.startTime,
    end_time: addTenMinutes(payload.startTime),
    appointment_source: payload.source || "Online",
    consultation_type: "General Consultation",
    visit_reason: payload.visitReason?.trim() || null,
    notes: payload.notes?.trim() || null,
    status: payload.status || "Confirmed",
    created_by: payload.createdBy,
    visit_group_id: payload.visitGroupId || null
  };
  const { data, error } = await supabase.from("appointments").insert(row).select("id, queue_number").single();
  if (error) {
    if (error.code === "23505") throw new Error("That appointment time was just booked. Please choose another slot.");
    const fallback = error.message?.includes("outside") || error.message?.includes("schedule") ? error.message : "Unable to book the appointment. Please try again.";
    throw new Error(describeDbError(error, fallback, "createAppointment"));
  }
  return data;
}

// Rollback helper for a partially-created multi-pet booking batch: cancels
// the appointments that already succeeded in this submission so a failure
// partway through doesn't leave orphaned bookings behind.
export async function cancelAppointmentsByIds(ids) {
  if (!ids?.length) return;
  try {
    await supabase.from("appointments").update({ status: "Cancelled" }).in("id", ids).eq("status", "Confirmed");
  } catch {
    // Best-effort rollback -- the caller already has a primary error to show.
  }
}

export async function sendGuestBookingConfirmationEmail(details) {
  const { data, error } = await supabase.functions.invoke("send-booking-confirmation-email", { body: details });
  if (error) {
    let message = error.message || "Unable to send the confirmation email.";
    try {
      const body = await error.context?.json();
      message = body?.error || body?.message || message;
    } catch {}
    throw new Error(message);
  }
  if (data?.error) throw new Error(data.error);
  return data;
}

export async function getAppointments(filters = {}) {
  let query = supabase.from("appointments").select(`
    id, appointment_date, start_time, end_time, appointment_source, consultation_type,
    visit_reason, notes, status, visit_group_id, created_at, updated_at,
    pet:pets(id, pet_name, species, breed, photo_url),
    owner:profiles!appointments_owner_id_fkey(id, full_name, email, username, avatar_url),
    veterinarian:profiles!appointments_veterinarian_id_fkey(id, full_name)
  `).order("appointment_date", { ascending: false }).order("start_time", { ascending: true });
  if (filters.ownerId) query = query.eq("owner_id", filters.ownerId);
  if (filters.veterinarianId) query = query.eq("veterinarian_id", filters.veterinarianId);
  if (filters.status) query = query.eq("status", filters.status);
  if (filters.date) query = query.eq("appointment_date", filters.date);
  const { data, error } = await query;
  if (error) throw new Error("Unable to load appointments. Check the SQL relationships.");
  return data || [];
}

// Appointments that already have a queue ticket (checked in at the clinic),
// directly or as one pet of a shared multi-pet ticket.
export async function getCheckedInAppointmentIds(appointmentIds) {
  const ids = [...new Set((appointmentIds || []).filter(Boolean))];
  if (!ids.length) return new Set();
  const [{ data: direct }, { data: shared }] = await Promise.all([
    supabase.from("queue_entries").select("appointment_id").in("appointment_id", ids),
    supabase.from("queue_entry_pets").select("appointment_id").in("appointment_id", ids)
  ]);
  return new Set([...(direct || []), ...(shared || [])].map(row => row.appointment_id).filter(Boolean));
}

function checkedInError() {
  const error = new Error("This pet has already checked in at the clinic, so the appointment can no longer be cancelled.");
  error.code = "NOT_ELIGIBLE";
  return error;
}

// Thrown when a cancel finds the appointment already completed or
// cancelled (e.g. staff finished the visit while the list was open).
async function notEligibleForCancellation(id) {
  const { data } = await supabase.from("appointments").select("status").eq("id", id).maybeSingle();
  const reason = data?.status === "Completed"
    ? "This appointment is already completed."
    : data?.status === "Cancelled"
      ? "This appointment is already cancelled."
      : "This appointment can no longer be cancelled. Refresh the list to see its latest status.";
  const error = new Error(reason);
  error.code = "NOT_ELIGIBLE";
  return error;
}

export async function updateAppointmentStatus(id, status, changedBy) {
  if (!APPOINTMENT_STATUSES.includes(status)) throw new Error("Invalid appointment status.");
  if (status === "Cancelled" && (await getCheckedInAppointmentIds([id])).has(id)) throw checkedInError();
  let query = supabase.from("appointments")
    .update({ status, created_by: changedBy }).eq("id", id);
  // Only a Confirmed appointment can be cancelled.
  if (status === "Cancelled") query = query.eq("status", "Confirmed");
  const { data, error } = await query.select("id");
  if (error) throw new Error("Unable to update appointment status.");
  if (status === "Cancelled" && !data?.length) throw await notEligibleForCancellation(id);
}

export async function cancelAppointment(id, ownerId) {
  if ((await getCheckedInAppointmentIds([id])).has(id)) throw checkedInError();
  const { data, error } = await supabase.from("appointments")
    .update({ status: "Cancelled" }).eq("id", id).eq("owner_id", ownerId)
    .eq("status", "Confirmed")
    .select("id");
  if (error) throw new Error("Unable to cancel the appointment.");
  if (!data?.length) throw await notEligibleForCancellation(id);
}

// Rebooking keeps the same pet and owner, so only what changes is checked.
function validateReschedule(id, values) {
  if (!id) throw new Error("This appointment can't be found. Refresh the list and try again.");
  if (!values.veterinarianId) throw new Error("Select a veterinarian.");
  if (!values.appointmentDate || values.appointmentDate < todayLocal()) throw new Error("Select today or a future date.");
  if (!values.startTime) throw new Error("Select an available time.");
}

// ownerId: pass it when a pet owner rebooks (they can only move their own
// appointments); staff, admins and vets may leave it empty.
export async function rescheduleAppointment(id, values, ownerId, changedBy) {
  validateReschedule(id, values);

  const latestSlots = await getAvailableSlots(
    values.veterinarianId,
    values.appointmentDate,
    id
  );
  if (!latestSlots.includes(normalizeTime(values.startTime))) {
    throw new Error("That appointment time is no longer available. Please choose another time.");
  }

  let query = supabase.from("appointments").update({
    veterinarian_id: values.veterinarianId,
    appointment_date: values.appointmentDate,
    start_time: values.startTime,
    end_time: addTenMinutes(values.startTime),
    status: "Confirmed",
    created_by: changedBy
  }).eq("id", id).eq("status", "Confirmed");
  if (ownerId) query = query.eq("owner_id", ownerId);
  const { data, error } = await query.select("id");
  if (error) {
    if (error.code === "23505") throw new Error("That time is already booked.");
    // The booking check explains schedule problems (e.g. no schedule yet).
    const reason = String(error.message || "");
    if (/schedule|unavailable|outside|past/i.test(reason)) throw new Error(reason);
    throw new Error("Unable to reschedule the appointment.");
  }
  if (!data?.length) throw new Error("This appointment is no longer active. Refresh the list and try again.");
}

// Guaranteed to satisfy the app-wide password policy (8+ chars, upper,
// lower, number, special) so a guest's temp password never fails the same
// checklist they're required to meet when they change it on first login.
export function generateTempPassword() {
  const upper = "ABCDEFGHJKMNPQRSTUVWXYZ";
  const lower = "abcdefghjkmnpqrstuvwxyz";
  const digits = "23456789";
  const special = "!@#$%^&*";
  const all = upper + lower + digits + special;
  const pick = (set) => set[Math.floor(Math.random() * set.length)];

  const required = [pick(upper), pick(lower), pick(digits), pick(special)];
  const rest = Array.from({ length: 6 }, () => pick(all));

  const value = [...required, ...rest];
  for (let i = value.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [value[i], value[j]] = [value[j], value[i]];
  }
  return value.join("");
}

/**
 * Registers a brand-new walk-in Pet Owner. Always creates a new account
 * (this is the "guest, no existing account" path -- an existing owner is
 * found through the separate search-and-select flow instead), so the
 * Data Privacy Consent captured on the walk-in form is recorded here via
 * the same atomic pawcruz_create_pet_owner_with_consent RPC used by
 * self-registration -- the profile and its consent record(s) are created
 * in one transaction, never against a temporary/fake id.
 */
export async function createGuestOwner({ fullName, phone, email, address, marketingConsent = false, recordedBy = null, sourceContext = "Walk-in Registration" }) {
  const trimmedName = fullName?.trim();
  const trimmedEmail = email?.trim().toLowerCase();
  const trimmedPhone = phone?.trim();
  const trimmedAddress = address?.trim();
  if (!trimmedName || !trimmedEmail || !trimmedPhone || !trimmedAddress) {
    throw new Error("Full name, phone, email, and address are required.");
  }
  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailPattern.test(trimmedEmail)) throw new Error("Enter a valid email address.");
  if (!isValidPhMobile(trimmedPhone)) throw new Error(INVALID_PH_MOBILE_MESSAGE);
  const slug = trimmedName.toLowerCase().replace(/[^a-z0-9]+/g, "").slice(0, 16) || "guest";
  const username = `${slug}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  const tempPassword = generateTempPassword();
  const { data, error } = await supabase.rpc("pawcruz_create_pet_owner_with_consent", {
    p_full_name: trimmedName,
    p_username: username,
    p_email: trimmedEmail,
    p_password: tempPassword,
    p_marketing_consent: Boolean(marketingConsent),
    p_privacy_notice_version: PRIVACY_NOTICE_VERSION,
    p_source_context: sourceContext,
    p_method: "Staff Walk-in Form",
    p_phone: trimmedPhone,
    p_address: trimmedAddress,
    p_must_change_password: true,
    p_recorded_by: recordedBy,
  });
  if (error) {
    if (error.code === "23505" || /already registered/i.test(error.message || "")) throw new Error("That email is already registered. Search for them as an existing pet owner instead.");
    throw new Error(describeDbError(error, "Unable to register the guest. Please check the details and try again.", "createGuestOwner"));
  }
  return { id: data.id, full_name: data.full_name, username: data.username, email: data.email, phone: data.phone, address: data.address, tempPassword };
}

export async function sendGuestAccountEmail(details) {
  const { data, error } = await supabase.functions.invoke("send-guest-account-email", { body: details });
  if (error) {
    let message = error.message || "Unable to send the account email.";
    try {
      const body = await error.context?.json();
      message = body?.error || body?.message || message;
    } catch {}
    throw new Error(message);
  }
  if (data?.error) throw new Error(data.error);
  return data;
}

export async function createPet(ownerId, values) {
  if (!ownerId || !values.petName?.trim() || !values.species?.trim()) throw new Error("Owner, pet name, and species are required.");
  const { data, error } = await supabase.from("pets").insert({
    owner_id: ownerId,
    pet_name: values.petName.trim(),
    species: values.species.trim(),
    breed: values.breed?.trim() || null,
    sex: values.sex || "Unknown"
  }).select("*").single();
  if (error) throw new Error(describeDbError(error, "Unable to register the pet. Please try again.", "createPet"));
  return data;
}
